css:
@font-face {
	font-family: 'Harbour Lato';
	src: url('./fonts/Lato-Regular.woff2') format('woff2');
	font-weight: 400;
}

@font-face {
	font-family: 'Harbour Lato';
	src: url('./fonts/Lato-Bold.woff2') format('woff2');
	font-weight: 700;
}

body {
	margin: 0;
	font-family: 'Nowhere Sans', 'Harbour Lato';
}

.page.mk-134lmnt {
				padding: 24px;
				background: #f8f9fa;
			}
			.heading.mk-134lmnt {
				font-size: 26px;
				font-weight: 700;
				color: #212529;
			}
			.notes.mk-134lmnt {
				margin: 16px 0 0;
				padding: 0;
				list-style: none;
			}
			.note.mk-134lmnt {
				display: flex;
				align-items: center;
				gap: 12px;
				margin-top: 8px;
				padding: 12px 16px;
				border: 1px solid #ced4da;
				border-radius: 10px;
				background: #ffffff;
			}
			.note.pinned.mk-134lmnt {
				border-color: #e9c46a;
				background: #fff8e1;
			}
			.title.mk-134lmnt {
				flex: 1;
				font-size: 17px;
				color: #212529;
			}
			.empty.mk-134lmnt {
				margin-top: 16px;
				color: #6c757d;
				font-size: 15px;
			}
			.action.mk-134lmnt {
				display: block;
				width: 100%;
				margin-top: 12px;
				padding: 10px 16px;
				border: 2px solid #264653;
				border-radius: 10px;
				background: #ffffff;
				color: #264653;
				font-family: inherit;
				font-size: 17px;
				text-align: left;
			}
			.footer.mk-134lmnt {
				margin-top: 24px;
				padding-top: 12px;
				border-top: 1px solid #adb5bd;
				color: #495057;
				font-size: 15px;
			}
